import{z as s,x as B,o as i,c as p,q as t,j as l,D as o,d as e,s as r,S as P,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"多恩布什超调","description":"","frontmatter":{"title":"多恩布什超调","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dornbusch-overshoot.md","filePath":"econ/dornbusch-overshoot.md","lastUpdated":1791063341000}'),d={name:"econ/dornbusch-overshoot.md"};function A(D,a,m,u,h,C){const n=B("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="多恩布什超调" tabindex="-1">多恩布什超调 <a class="header-anchor" href="#多恩布什超调" aria-label="Permalink to &quot;多恩布什超调&quot;">​</a></h1><div class="epigraph"><p>物价粘住时，货币扩张必须让汇率立刻贬过长期 PPP 水平，预期中的升值才能对齐已经下降的利率。</p><footer>—— Dornbusch, Expectations and Exchange Rate Dynamics, Journal of Political Economy 1976</footer></div><p><a href="/econ/mundell-fleming">上一课</a>在静态预期下给出固定与浮动的分叉：\\(i\\) 贴近 \\(i^*\\)，流量 IS 决定 \\(Y\\)。本课的缺口是理性预期补丁：物价短期粘、长期回到 PPP，UIP 要求 \\(E\\) 先走过头。不可能三角是再下一课把制度收成三选二；本课只把超调钉进已经打开的浮动角。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MF 用静态预期，\\(i=i^*\\)。一旦允许 \\(\\mathbb{E}\\Delta e\\neq 0\\)，UIP 写成 \\(i=i^*+\\mathbb{E}\\Delta e\\)。货币扩张立刻压低 \\(i\\)，若 \\(E\\) 只走到长期 PPP，预期贬值率为零，UIP 不平。Dornbusch 的缺口是：粘性 \\(P\\) 下，\\(E\\) 必须立刻贬到超过长期水平，使随后的路径是<strong>预期升值</strong>，正好补上 \\(i-i^*\\)。长期 \\(P\\) 按数量论（或相对 PPP）追上，\\(E\\) 从超调点爬回，实际汇率 \\(q\\) 的大摆动是过渡，不是新的恒等。</p><p>MF 已经给出浮动角上货币相对有效。本课不加新恒等，只把静态 \\(i=i^*\\) 换成带预期的 UIP，让 \\(E\\) 的瞬时值可以离开长期 PPP。三角课仍用制度分叉，不需要再推一遍超调代数。实证基差不在此报，见 <code>/quant/irp</code>。</p><p><span class="marginnote">超调是资产市场快、货物市场慢的相对速度，不是「非理性过冲」。理性预期下，走过头是均衡，不是误差。</span></p><p><span class="marginnote">数字实例：设长期汇率为 100，扩张后本国利率比国外低 2 个百分点、物价要三年才调整完。UIP 要求每年预期升值约 2%，于是当下汇率须贬到约 106 的过头位置，再每年升 2% 爬回 100——『先贬过头』是补齐利率差的算术要求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>商品市场：\\(P\\) 按超额需求缓慢调整（或 Calvo 式粘性，精神相同）。资产市场：UIP 每期成立，资本高度流动。长期：货币中性，\\(E\\) 与 \\(P\\) 同比例升， \\(q\\) 回初始。短局：\\(P\\) 不动，\\(M\\) 升使 \\(i\\) 降，\\(E\\) 跳到超调点。动态上 \\(E\\) 的预期变化钉住利率差，直到 \\(P\\) 完成调整。</p>',10)),(i(),l(P,null,{default:o(()=>[r(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E8%B4%A7%E5%B8%81%E6%89%A9%E5%BC%A0%22%5D%20--%3E%20I%5B%22i%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20I%20--%3E%20UIP%5B%22UIP%EF%BC%9A%E9%9C%80%E8%A6%81%20E%CE%94e%22%5D%0A%20%20UIP%20--%3E%20OS%5B%22E%20%E8%B4%AC%E8%BF%87%E9%95%BF%E6%9C%9F%20PPP%22%5D%0A%20%20OS%20--%3E%20EXP%5B%22%E9%9A%8F%E5%90%8E%E9%A2%84%E6%9C%9F%E5%8D%87%E5%80%BC%22%5D%0A%20%20P%5B%22%E7%B2%98%E6%80%A7%20P%20%E6%85%A2%E6%85%A2%E5%8D%87%22%5D%20--%3E%20BACK%5B%22E%20%E7%88%AC%E5%9B%9E%20PPP%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("这与巴拉萨–萨缪尔森不冲突：后者是可贸易生产率造成的 \\(q\\) 趋势；超调是名义冲击下的过渡路径。CIP 仍是远期会计，见 "),E("code",null,"/quant/irp"),e("；超调用的是 UIP，不报基差。")],-1)),a[4]||(a[4]=E("h3",{id:"仍是会计加均衡",tabindex:"-1"},[e("仍是会计加均衡 "),E("a",{class:"header-anchor",href:"#仍是会计加均衡","aria-label":'Permalink to "仍是会计加均衡"'},"​")],-1)),a[5]||(a[5]=E("p",null,"\\(CA=S-I\\) 事后成立。超调改变的是 \\(q\\) 从而支出转换与吸收，均衡中的 \\(CA\\) 可以摆，恒等不破。MF 的「浮动时货币更有效」在此有了汇率通道的放大：同样的 \\(M\\)，\\(q\\) 的瞬时变动大于长期，净出口的短反应可以大于 PPP 所暗示的。",-1)),a[6]||(a[6]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=E("p",null,"资产持有者要求本币存款与外币存款（加预期升贬值）回报相等。\\(i\\) 被货币扩张压低的瞬间，唯一能出清的是预期本币升值，因而当前 \\(E\\) 必须已经贬得足够远。物价粘性使实际余额 \\(M/P\\) 上升，这正是 \\(i\\) 下降的来源；若 \\(P\\) 立刻灵活，费雪与 PPP 同时跳，\\(i\\) 与 \\(E\\) 一步到位，没有超调。长期中性恢复：\\(\\tilde{y}=0\\)，\\(\\pi\\) 由新的货币路径决定。自然率不因 \\(E\\) 的名义跳而永久改变。",-1)),a[8]||(a[8]=E("p",null,"「为什么必须是粘性物价才有超调」——同一笔冲击在两种物价下的分叉：",-1)),(i(),l(P,null,{default:o(()=>[r(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E8%B4%A7%E5%B8%81%E6%89%A9%E5%BC%A0%22%5D%20--%3E%20FLEX%5B%22%E7%89%A9%E4%BB%B7%E7%AB%8B%E5%88%BB%E7%81%B5%E6%B4%BB%22%5D%0A%20%20M%20--%3E%20STICK%5B%22%E7%89%A9%E4%BB%B7%E7%9F%AD%E6%9C%9F%E7%B2%98%E4%BD%8F%22%5D%0A%20%20FLEX%20--%3E%20F1%5B%22P%20%E4%B8%8E%20E%20%E5%90%8C%E6%AD%A5%E8%B7%B3%E5%88%B0%E6%96%B0%E9%95%BF%E6%9C%9F%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E5%88%A9%E7%8E%87%E4%B8%8D%E5%8F%98%2C%20%E6%B2%A1%E6%9C%89%E8%B6%85%E8%B0%83%22%5D%0A%20%20STICK%20--%3E%20S1%5B%22P%20%E4%B8%8D%E5%8A%A8%2C%20%E5%AE%9E%E9%99%85%E4%BD%99%E9%A2%9D%20M%2FP%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%88%A9%E7%8E%87%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20S2%20--%3E%20S3%5B%22E%20%E8%B4%AC%E8%BF%87%E5%A4%B4%2C%20%E6%AD%A4%E5%90%8E%E9%A2%84%E6%9C%9F%E5%8D%87%E5%80%BC%E5%9B%9E%20PPP%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=t('<p><span class="marginnote">类比一根拴在长期 PPP 位置的弹簧：物价是拴住它的绳子。货币冲击一来，绳子还没松开，弹簧只能被瞬间拉过头；等物价慢慢跟上，弹簧再缓缓收回原位——走过头本身就是后来能回位的必要条件。</span></p><p>时间不一致不在 1976 年的原文里，但可读：宣布的货币路径若不可信，超调的终点不是 PPP 算出的那个 \\(E\\)，储备或风险溢价会另写一项。本课先取可信规则下的超调。MF 的浮动角上「货币更有效」在此有了放大：瞬时 \\(q\\) 的变动大于长期 PPP，支出转换可以过冲。突然停止切断的是 UIP 所假设的资本流动，超调公式不再适用——那是后课，本课资本仍高度流动。</p><p><span class="marginnote">大国 \\(i^*\\) 内生、风险溢价随头寸变，超调幅度改，符号机制可以还在。原模型是小国、静态价格调整方程，不是 NK 开放经济的全套校准。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>静态 MF 没有微观基础的 NX；Dornbusch 补的是预期与粘性 \\(P\\)，仍不是完整的开放 NK。不要把超调写成对限价簿的外汇订单。也不要把某一周的汇率波动都叫超调——还要有名义冲击与粘性物价这两件家具。CIP 的短端会计不在此重导，实证见 <code>/quant/irp</code>。紧缩对称：货币收缩让 \\(E\\) 升过长期水平，随后预期贬值对齐偏高的 \\(i\\)。</p><p><span class="marginnote">注意超调说的是名义汇率 E 的事；物价粘住时实际汇率 q 同步大贬，出口竞争力短期大增，又随物价回升而消退。别把这条过渡红利当成可持续的比较优势写进长期判断。</span></p><p>原罪会让同一 \\(\\Delta e\\) 变成净值税，超调的福利符号可以翻。本课资本仍按 UIP 流动、债的币种未写。三角下一课收成三选二，超调只活在已经打开的浮动角。</p><p>后课默认：浮动加粘性物价时，\\(E\\) 可以对名义冲击超调。下一课把独立货币、钉住、资本开放收成三选二。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>粘性 \\(P\\) + UIP：货币扩张让 \\(E\\) 贬过长期 PPP。</li><li>预期升值对齐利率差；\\(P\\) 追上后超调消失。</li><li>与巴拉萨–萨缪尔森的趋势 \\(q\\) 不是同一机制。</li><li>长期中性与相对 PPP 仍是终点。</li><li>资本仍流动；突然停止会切断本课的 UIP 装置。</li><li>出处：Dornbusch, <em>JPE</em> 1976。</li></ul>',10))])}const f=s(d,[["render",A]]);export{b as __pageData,f as default};
